tiles = [
    # origin y,x, color, 3x3 motif rows (1 means erase to background)
    (1,7,1,[[0,0,1],[1,1,1],[0,0,1]]),
    (1,13,3,[[0,1,1],[0,1,1],[1,0,0]]),
    (7,7,7,[[0,1,1],[1,1,0],[0,0,1]]),
    (7,13,5,[[0,1,1],[1,1,0],[0,1,1]]),
]
out = [[6]*19 for _ in range(13)]
for y,x,c,mask in tiles:
    for dy in range(5):
        for dx in range(5):
            out[y+dy][x+dx]=c
    for dy in range(3):
        for dx in range(3):
            if mask[dy][dx]: out[y+1+dy][x+1+dx]=6
print('\n'.join(' '.join(map(str,row)) for row in out))
